const item = $input.first().json;
const cfg = {
  pagerduty_base_url: item.pagerduty_base_url,
  confluence_base_url: item.confluence_base_url,
  confluence_space_key: item.confluence_space_key,
  confluence_parent_page_id: item.confluence_parent_page_id,
  slack_channel_id: item.slack_channel_id,
  postmortem_owner: item.postmortem_owner,
  google_sheets_spreadsheet_id: item.google_sheets_spreadsheet_id,
  minimum_severity_for_postmortem: item.minimum_severity_for_postmortem,
  include_action_items: item.include_action_items === true || item.include_action_items === 'true',
  publish_as_draft: item.publish_as_draft === true || item.publish_as_draft === 'true',
};

const payload = item.body || item.event || item;
const incident = payload.incident || payload.data || payload;
const now = new Date();

return [{
  json: {
    config: cfg,
    incidentId: incident.id || 'PABC123',
    incidentNumber: incident.incident_number || incident.number || '1001',
    incidentTitle: incident.title || incident.summary || 'Checkout API latency increase',
    serviceName: incident.service?.summary || incident.service_name || 'Checkout API',
    status: incident.status || 'resolved',
    urgency: incident.urgency || 'high',
    severity: incident.severity || 'P2',
    htmlUrl: incident.html_url || 'https://pagerduty.example/incidents/PABC123',
    createdAt: incident.created_at || new Date(now.getTime() - 90*60*1000).toISOString(),
    resolvedAt: incident.resolved_at || now.toISOString(),
    owner: incident.assignments?.[0]?.assignee?.summary || cfg.postmortem_owner,
  }
}];

const source = $input.first().json;
            const cfg = source.config || {};
            const start = new Date(source.createdAt || Date.now());
            const end = new Date(source.resolvedAt || Date.now());
            const minutes = Math.max(0, Math.round((end - start) / 60000));

            const timeline = [
              `- ${start.toISOString()} Incident opened for ${source.serviceName}`,
              `- ${new Date(start.getTime() + 15*60000).toISOString()} Initial triage started by ${source.owner}`,
              `- ${new Date(start.getTime() + 45*60000).toISOString()} Mitigation applied or rollback started`,
              `- ${end.toISOString()} Incident resolved`
            ];

            const title = `Postmortem: ${source.incidentTitle} (${source.incidentNumber})`;
            const storage = `
<h2>Summary</h2>
<p>${source.incidentTitle}</p>
<h2>Impact</h2>
<p>Document customer impact, affected regions, and affected product areas here.</p>
<h2>Incident details</h2>
<ul>
  <li>PagerDuty incident: ${source.htmlUrl}</li>
  <li>Service: ${source.serviceName}</li>
  <li>Severity: ${source.severity}</li>
  <li>Duration: ${minutes} minutes</li>
  <li>Owner: ${source.owner}</li>
</ul>
<h2>Timeline</h2>
<pre>${timeline.join('\n')}</pre>
<h2>Root cause</h2>
<p>Needs review. Add the confirmed root cause after engineering review.</p>
<h2>What went well</h2>
<ul><li>Needs review.</li></ul>
<h2>What can improve</h2>
<ul><li>Needs review.</li></ul>
<h2>Action items</h2>
<ul>
  <li>[ ] Add owner, due date, and ticket link for each remediation item.</li>
</ul>`.trim();

            return [{
              json: {
                ...source,
                postmortemTitle: title,
                confluenceStorageBody: storage,
                durationMinutes: minutes,
                createdForReview: true
              }
            }];
